mapper.select:
SELECT TRUNC(r.real_start_time) AS date, -- 按日期分组，TRUNC将时间截断到日期部分 COUNT(s.id) AS total_sign_count, SUM(CASE WHEN s.type = 1 THEN 1 ELSE 0 END) AS normal_sign_count, ROUND(100.0 * SUM(CASE WHEN s.type = 1 THEN 1 ELSE 0 END) / NULLIF(COUNT(s.id), 0), 2) AS normalSignRate FROM bbx_meeting_reserve r INNER JOIN bbx_meeting_reserve_sign s ON r.id = s.reserve_id WHERE r.in_valid_flag = 0 AND cancel_flag = 0 AND r.real_start_time >= TRUNC(SYSDATE) - 30 -- 30天前
AND r.tenant_id =#{tenantId}
GROUP BY date ORDER BY date;
